17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.controller.BindingErrorsResponse;
32	import org.springframework.samples.petclinic.rest.controller.CityOwnerLimitExceededException;
33	import org.springframework.samples.petclinic.rest.controller.DailyOwnerLimitExceededException;
34	import org.springframework.samples.petclinic.rest.controller.DisposableEmailDomainException;
35	import org.springframework.samples.petclinic.rest.controller.DuplicateIdentityException;
36	import org.springframework.samples.petclinic.rest.controller.FutureRegistrationDateException;
37	import org.springframework.samples.petclinic.rest.controller.HouseholdDuplicateException;
38	import org.springframework.samples.petclinic.rest.controller.InvalidEmailException;
39	import org.springframework.samples.petclinic.rest.controller.InvalidPostcodeException;
40	import org.springframework.samples.petclinic.rest.controller.InvalidTelephoneException;
41	import org.springframework.samples.petclinic.rest.controller.RequiredFieldsMissingException;
42	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
43	import org.springframework.security.access.AccessDeniedException;
44	import org.springframework.validation.BindingResult;
45	import org.springframework.validation.FieldError;
46	import org.springframework.web.bind.MethodArgumentNotValidException;
47	import org.springframework.web.bind.annotation.ControllerAdvice;
48	import org.springframework.web.bind.annotation.ExceptionHandler;
49	import org.springframework.web.bind.annotation.ResponseBody;
50	
51	/**
52	 * Global Exception handler for REST controllers.
53	 * <p>
54	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
55	 *
56	 * @author Vitaliy Fedoriv
57	 * @author Alexander Dudkin
58	 */
59	@ControllerAdvice
60	public class ExceptionControllerAdvice {
61	
62	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
63	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
64	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
65	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
66	    private static final String ERROR_DUPLICATE_IDENTITY = "An owner with the given identity already exists";
67	    private static final String ERROR_HOUSEHOLD_DUPLICATE = "An owner already belongs to this household";
68	    private static final String ERROR_CITY_AT_CAPACITY = "The owner's city already contains the maximum number of owners";
69	    private static final String ERROR_DAILY_LIMIT = "The maximum number of owners for today has already been reached";
70	    private static final String ERROR_FUTURE_REGISTRATION_DATE = "The supplied registrationDate must not be later than the server date";
71	
72	    /**
73	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
74	     * class.
75	     *
76	     * @param e     Object referring to the thrown exception.
77	     * @param status HTTP response status.
78	     * @param url URL request.
79	     */
80	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
81	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
82	        problemDetail.setType(URI.create(url.toString()));
83	        problemDetail.setTitle(e.getClass().getSimpleName());
84	        problemDetail.setDetail(detail);
85	        problemDetail.setProperty("timestamp", Instant.now());
86	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
87	        return problemDetail;
88	    }
89	
90	    /**
91	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
92	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
93	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
94	     * would catch it and report an authorization failure as a 500.
95	     *
96	     * @param e The {@link AccessDeniedException} to propagate
97	     * @throws AccessDeniedException always
98	     */
99	    @ExceptionHandler(AccessDeniedException.class)
100	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
101	        throw e;
102	    }
103	
104	    /**
105	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
106	     *
107	     * @param e The {@link Exception} to be handled
108	     * @param request {@link HttpServletRequest} object referring to the current request.
109	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
110	     */
111	    @ExceptionHandler(Exception.class)
112	    @ResponseBody
113	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
114	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
115	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
116	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
117	        return ResponseEntity.status(status).body(detail);
118	    }
119	
120	    /**
121	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
122	     * method returns a 404 Not Found status if an entity does not exist.
123	     *
124	     * @param e The {@link DataIntegrityViolationException} to be handled
125	     * @param request {@link HttpServletRequest} object referring to the current request.
126	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
127	     */
128	    @ExceptionHandler(DataIntegrityViolationException.class)
129	    @ResponseBody
130	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
131	        logger.warn("Data integrity violation at {} {}: {}",
132	            request.getMethod(),
133	            request.getRequestURI(),
134	            e.getMessage());
135	        logger.debug("Data integrity violation stacktrace", e);
136	        HttpStatus status = HttpStatus.NOT_FOUND;
137	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
138	        return ResponseEntity.status(status).body(detail);
139	    }
140	
141	    /**
142	     * Handles exception thrown by Bean Validation on controller methods parameters
143	     *
144	     * @param e The {@link MethodArgumentNotValidException} to be handled
145	     * @param request {@link HttpServletRequest} object referring to the current request.
146	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
147	     */
148	    @ExceptionHandler(MethodArgumentNotValidException.class)
149	    @ResponseBody
150	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
151	        HttpStatus status = HttpStatus.BAD_REQUEST;
152	        BindingErrorsResponse errors = new BindingErrorsResponse();
153	        BindingResult bindingResult = e.getBindingResult();
154	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
155	        List<String> invalidFields = bindingResult.getFieldErrors().stream()
156	            .map(FieldError::getField)
157	            .distinct()
158	            .toList();
159	        detail.setProperty("errors", invalidFields);
160	        if (bindingResult.hasErrors()) {
161	            errors.addAllErrors(bindingResult);
162	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
163	                .map(fieldError -> {
164	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
165	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
166	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
167	                        fieldError.getField(),
168	                        defaultMessage,
169	                        rejectedValue);
170	                    return new ValidationMessageDto(message)
171	                        .putAdditionalProperty("field", fieldError.getField())
172	                        .putAdditionalProperty("rejectedValue", rejectedValue)
173	                        .putAdditionalProperty("defaultMessage", defaultMessage);
174	                })
175	                .toList();
176	            logger.debug("Validation error at {} {}: {}",
177	                request.getMethod(),
178	                request.getRequestURI(),
179	                bindingResult.getFieldErrors());
180	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
181	            return ResponseEntity.status(status).body(detail);
182	        }
183	        return ResponseEntity.status(status).body(detail);
184	    }
185	
186	    /**
187	     * Handles {@link RequiredFieldsMissingException} raised when a create/update request omits or blanks a
188	     * mandatory owner field that Bean Validation cannot reject on its own (e.g. a whitespace-only value that
189	     * still satisfies a minimum-length constraint).
190	     *
191	     * @param e The {@link RequiredFieldsMissingException} to be handled
192	     * @param request {@link HttpServletRequest} object referring to the current request.
193	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
194	     */
195	    @ExceptionHandler(RequiredFieldsMissingException.class)
196	    @ResponseBody
197	    public ResponseEntity<ProblemDetail> handleRequiredFieldsMissingException(RequiredFieldsMissingException e, HttpServletRequest request) {
198	        HttpStatus status = HttpStatus.BAD_REQUEST;
199	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
200	        detail.setProperty("errors", e.getFields());
201	        logger.debug("Missing required fields at {} {}: {}",
202	            request.getMethod(),
203	            request.getRequestURI(),
204	            e.getFields());
205	        return ResponseEntity.status(status).body(detail);
206	    }
207	
208	    /**
209	     * Handles {@link InvalidTelephoneException} raised when a submitted telephone number does not
210	     * normalize to exactly ten digits.
211	     *
212	     * @param e The {@link InvalidTelephoneException} to be handled
213	     * @param request {@link HttpServletRequest} object referring to the current request.
214	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
215	     */
216	    @ExceptionHandler(InvalidTelephoneException.class)
217	    @ResponseBody
218	    public ResponseEntity<ProblemDetail> handleInvalidTelephoneException(InvalidTelephoneException e, HttpServletRequest request) {
219	        HttpStatus status = HttpStatus.BAD_REQUEST;
220	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
221	        detail.setProperty("errors", List.of("telephone"));
222	        logger.debug("Invalid telephone at {} {}: {}",
223	            request.getMethod(),
224	            request.getRequestURI(),
225	            e.getMessage());
226	        return ResponseEntity.status(status).body(detail);
227	    }
228	
229	    /**
230	     * Handles {@link InvalidEmailException} raised when a submitted owner {@code email} is present but is
231	     * not a syntactically valid address.
232	     *
233	     * @param e The {@link InvalidEmailException} to be handled
234	     * @param request {@link HttpServletRequest} object referring to the current request.
235	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
236	     */
237	    @ExceptionHandler(InvalidEmailException.class)
238	    @ResponseBody
239	    public ResponseEntity<ProblemDetail> handleInvalidEmailException(InvalidEmailException e, HttpServletRequest request) {
240	        HttpStatus status = HttpStatus.BAD_REQUEST;
241	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
242	        detail.setProperty("errors", List.of("email"));
243	        logger.debug("Invalid email at {} {}: {}",
244	            request.getMethod(),
245	            request.getRequestURI(),
246	            e.getMessage());
247	        return ResponseEntity.status(status).body(detail);
248	    }
249	
250	    /**
251	     * Handles {@link DisposableEmailDomainException} raised when a submitted owner {@code email} has a
252	     * domain on the disposable-domain blocklist (e.g. mailinator.com).
253	     *
254	     * @param e The {@link DisposableEmailDomainException} to be handled
255	     * @param request {@link HttpServletRequest} object referring to the current request.
256	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
257	     */
258	    @ExceptionHandler(DisposableEmailDomainException.class)
259	    @ResponseBody
260	    public ResponseEntity<ProblemDetail> handleDisposableEmailDomainException(DisposableEmailDomainException e, HttpServletRequest request) {
261	        HttpStatus status = HttpStatus.BAD_REQUEST;
262	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
263	        detail.setProperty("errors", List.of("email"));
264	        logger.debug("Disposable email domain at {} {}: {}",
265	            request.getMethod(),
266	            request.getRequestURI(),
267	            e.getMessage());
268	        return ResponseEntity.status(status).body(detail);
269	    }
270	
271	    /**
272	     * Handles {@link InvalidPostcodeException} raised when a submitted owner {@code postcode} is present
273	     * but is not a 4-digit value, or is out of range for the owner's city region (NSW 2000-2099,
274	     * VIC 3000-3099, QLD 4000-4099).
275	     *
276	     * @param e The {@link InvalidPostcodeException} to be handled
277	     * @param request {@link HttpServletRequest} object referring to the current request.
278	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
279	     */
280	    @ExceptionHandler(InvalidPostcodeException.class)
281	    @ResponseBody
282	    public ResponseEntity<ProblemDetail> handleInvalidPostcodeException(InvalidPostcodeException e, HttpServletRequest request) {
283	        HttpStatus status = HttpStatus.BAD_REQUEST;
284	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
285	        detail.setProperty("errors", List.of("postcode"));
286	        logger.debug("Invalid postcode at {} {}: {}",
287	            request.getMethod(),
288	            request.getRequestURI(),
289	            e.getMessage());
290	        return ResponseEntity.status(status).body(detail);
291	    }
292	
293	    /**
294	     * Handles {@link DuplicateIdentityException} raised when a create request supplies an owner whose
295	     * derived {@code identityKey} (normalized telephone, email or empty, and household id, joined by
296	     * {@code '|'}) exactly equals that of an existing owner. This single key subsumes the former separate
297	     * telephone, email and household duplicate checks.
298	     *
299	     * @param e The {@link DuplicateIdentityException} to be handled
300	     * @param request {@link HttpServletRequest} object referring to the current request.
301	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
302	     */
303	    @ExceptionHandler(DuplicateIdentityException.class)
304	    @ResponseBody
305	    public ResponseEntity<ProblemDetail> handleDuplicateIdentityException(DuplicateIdentityException e, HttpServletRequest request) {
306	        HttpStatus status = HttpStatus.CONFLICT;
307	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_IDENTITY);
308	        detail.setProperty("errors", List.of("identityKey"));
309	        logger.debug("Duplicate identity at {} {}: {}",
310	            request.getMethod(),
311	            request.getRequestURI(),
312	            e.getMessage());
313	        return ResponseEntity.status(status).body(detail);
314	    }
315	
316	    /**
317	     * Handles {@link HouseholdDuplicateException} raised when a create request supplies an owner that
318	     * would join an existing household (same computed {@code householdId}, derived from last name and
319	     * postcode) without declaring it via {@code sharesHousehold}.
320	     *
321	     * @param e The {@link HouseholdDuplicateException} to be handled
322	     * @param request {@link HttpServletRequest} object referring to the current request.
323	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
324	     */
325	    @ExceptionHandler(HouseholdDuplicateException.class)
326	    @ResponseBody
327	    public ResponseEntity<ProblemDetail> handleHouseholdDuplicateException(HouseholdDuplicateException e, HttpServletRequest request) {
328	        HttpStatus status = HttpStatus.CONFLICT;
329	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_HOUSEHOLD_DUPLICATE);
330	        detail.setProperty("errors", List.of("householdId"));
331	        logger.debug("Household duplicate at {} {}: {}",
332	            request.getMethod(),
333	            request.getRequestURI(),
334	            e.getMessage());
335	        return ResponseEntity.status(status).body(detail);
336	    }
337	
338	    /**
339	     * Handles {@link CityOwnerLimitExceededException} raised when a create request supplies an owner
340	     * whose city (compared case-insensitively) already contains the maximum permitted number of owners.
341	     *
342	     * @param e The {@link CityOwnerLimitExceededException} to be handled
343	     * @param request {@link HttpServletRequest} object referring to the current request.
344	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
345	     */
346	    @ExceptionHandler(CityOwnerLimitExceededException.class)
347	    @ResponseBody
348	    public ResponseEntity<ProblemDetail> handleCityOwnerLimitExceededException(CityOwnerLimitExceededException e, HttpServletRequest request) {
349	        HttpStatus status = HttpStatus.CONFLICT;
350	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_CITY_AT_CAPACITY);
351	        detail.setProperty("errors", List.of("city"));
352	        logger.debug("City at capacity at {} {}: {}",
353	            request.getMethod(),
354	            request.getRequestURI(),
355	            e.getMessage());
356	        return ResponseEntity.status(status).body(detail);
357	    }
358	
359	    /**
360	     * Handles {@link DailyOwnerLimitExceededException} raised when a create request would exceed the
361	     * maximum number of owners permitted to be created in a single day (compared by
362	     * {@code registrationDate}).
363	     *
364	     * @param e The {@link DailyOwnerLimitExceededException} to be handled
365	     * @param request {@link HttpServletRequest} object referring to the current request.
366	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status.
367	     */
368	    @ExceptionHandler(DailyOwnerLimitExceededException.class)
369	    @ResponseBody
370	    public ResponseEntity<ProblemDetail> handleDailyOwnerLimitExceededException(DailyOwnerLimitExceededException e, HttpServletRequest request) {
371	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
372	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DAILY_LIMIT);
373	        detail.setProperty("errors", List.of("registrationDate"));
374	        logger.debug("Daily owner limit reached at {} {}: {}",
375	            request.getMethod(),
376	            request.getRequestURI(),
377	            e.getMessage());
378	        return ResponseEntity.status(status).body(detail);
379	    }
380	
381	    /**
382	     * Handles {@link FutureRegistrationDateException} raised when a create request supplies a
383	     * {@code registrationDate} that is later than the server date.
384	     *
385	     * @param e The {@link FutureRegistrationDateException} to be handled
386	     * @param request {@link HttpServletRequest} object referring to the current request.
387	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
388	     */
389	    @ExceptionHandler(FutureRegistrationDateException.class)
390	    @ResponseBody
391	    public ResponseEntity<ProblemDetail> handleFutureRegistrationDateException(FutureRegistrationDateException e, HttpServletRequest request) {
392	        HttpStatus status = HttpStatus.BAD_REQUEST;
393	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_FUTURE_REGISTRATION_DATE);
394	        detail.setProperty("errors", List.of("registrationDate"));
395	        logger.debug("Future registration date at {} {}: {}",
396	            request.getMethod(),
397	            request.getRequestURI(),
398	            e.getMessage());
399	        return ResponseEntity.status(status).body(detail);
400	    }
401	
402	}
